from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            touches_edge = False
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not touches_edge:
                color = 7 if len(comp) % 2 else 2
                for y,x in comp:
                    out[y][x] = color
    return out

